xql_query:
// ============================================================
// Rule: BYT_Brute Force Authentication Attempt Detected
// Vendor: BeyondTrust
// Objective:
// Detect activity associated with BYT_Brute Force Authentication Attempt Detected.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1110 - Brute Force

// Fonte de dados: logs do BeyondTrust Password Safe
dataset = beyondtrust_passwordsafe_raw  

// Filtra apenas eventos da categoria "Login Failure"
| filter (category = """Login Failure""")  

// Restringe para falhas de autenticação com a mensagem "Invalid username or password"
| filter message = "Invalid username or password"  

// Agrupa os eventos em janelas de 10 minutos
| bin _time span=10m  

// Conta o número total de falhas por usuário dentro da janela de tempo
// Também coleta os endereços IP de origem relacionados às falhas
| comp count() as total_failures, values(src_ipv4) as ips by user, _time, description, message  

// Mantém apenas os casos onde foram registradas mais de 5 falhas no período
| filter total_failures > 10
